/**
 * @name Command injection via os.system
 * @description Using os.system with untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Use API graph to find os.system calls and get their command argument
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    ) or
    // Also check for subprocess.call, subprocess.Popen, etc.
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Multiple injection vulnerabilities
 * @description Check for various injection patterns with user input
 * @kind path-problem
 * @problem.severity error
 * @id py/multiple-injections
 * @tags security
 *        external/cwe/cwe-094
 *        external/cwe/cwe-078
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module InjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Code execution
    exists(API::CallNode call |
      call = API::builtin(["eval", "exec", "compile"]).getACall() and
      sink = call.getArg(0)
    ) or
    // Command execution
    exists(API::CallNode call |
      call = API::moduleImport("os").getMember("system").getACall() and
      sink = call.getArg(0)
    ) or
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember(["call", "run", "Popen"]).getACall() and
      sink = call.getArg(0)
    ) or
    // SQL execution (unlikely but checking)
    exists(API::CallNode call |
      call = API::moduleImport("sqlite3").getMember(["execute", "executescript"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module InjectionFlow = TaintTracking::Global<InjectionConfig>;
import InjectionFlow::PathGraph

from InjectionFlow::PathNode source, InjectionFlow::PathNode sink
where InjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Injection vulnerability from $@.", source.getNode(), "user input"
